class LmdbAlternateLocationSafetyTest {
	@ParameterizedTest
	@ValueSource(strings = { "unknown-owner", "symlink", "unknown-child" })
	void foreignAlternateOccupantsArePreservedWhileFeedbackRemainsUsable(String kind,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbStore initial = new LmdbStore(directory.toFile(), config());
		initial.init();
		initial.shutDown();
		LmdbLegacyV4TestFixture.install(directory);
		StoreProperties properties = new StoreProperties(directory.toFile());
		assertTrue(properties.load());
		UUID storeId = properties.getOrCreateStoreId();
		Path alternate = directory.resolve(".rdf4j-estimator-" + storeId);
		if (kind.equals("unknown-child")) {
			LmdbStore seed = new LmdbStore(directory.toFile(), config());
			try (AutoCloseable shutdown = seed::shutDown) {
				seed.init();
				LmdbTestUtil.awaitPostReadyInitialization(seed, 20, TimeUnit.SECONDS);
			}
			assertTrue(Files.isDirectory(alternate, LinkOption.NOFOLLOW_LINKS),
					"the real resolver created the alternate namespace");
			assertTrue(Files.isRegularFile(alternate.resolve("owner"), LinkOption.NOFOLLOW_LINKS),
					"the real owner record exists");
		}
		Path foreign = directory.resolve("foreign");
		Files.createDirectory(foreign);
		byte[] original = "unrelated alternate content".getBytes(StandardCharsets.UTF_8);
		Path protectedFile;
		switch (kind) {
		case "unknown-owner":
			Files.createDirectory(alternate);
			protectedFile = alternate.resolve("owner");
			Files.write(protectedFile, original, StandardOpenOption.CREATE_NEW);
			break;
		case "symlink":
			protectedFile = foreign.resolve("owner");
			Files.write(protectedFile, original, StandardOpenOption.CREATE_NEW);
			try {
				Files.createSymbolicLink(alternate, foreign);
			} catch (IOException | UnsupportedOperationException | SecurityException unavailable) {
				Assumptions.assumeTrue(false, "symbolic links are unavailable on this filesystem");
			}
			break;
		case "unknown-child":
			protectedFile = alternate.resolve("synopsis.filters");
			Files.write(protectedFile, original, StandardOpenOption.CREATE_NEW);
			break;
		default:
			throw new AssertionError(kind);
		}
		byte[] owner = kind.equals("unknown-child") ? Files.readAllBytes(alternate.resolve("owner")) : null;
		try (AutoCloseable preserve = () -> assertAll(
				() -> LmdbLegacyV4TestFixture.assertUnchanged(directory),
				() -> assertArrayEquals(original, Files.readAllBytes(protectedFile), "unrelated alternate file"),
				() -> {
					if (owner != null) {
						assertArrayEquals(owner, Files.readAllBytes(alternate.resolve("owner")),
								"the owner record remains");
					}
				},
				() -> {
					if (kind.equals("symlink")) {
						assertTrue(Files.isSymbolicLink(alternate));
					}
				})) {
			LmdbStore store = new LmdbStore(directory.toFile(), config());
			try (AutoCloseable shutdown = store::shutDown) {
				store.init();
				LmdbTestUtil.awaitPostReadyInitialization(store, 20, TimeUnit.SECONDS);
				LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
						.getEvaluationStatistics();
				statistics.bindExecutionSnapshot(OptionalLong.of(statistics.estimatorRuntime().snapshotVersion()));
				Filter filter = filter();
				statistics.recordFilterOutcome(filter, 20L, 80L);
				EvaluationStatistics.FilterPassEstimate estimate = statistics.estimateFilterPass(filter);
				assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER, estimate.getSource());
				assertEquals(100L, estimate.getEvidenceCount());
				if (kind.equals("unknown-child")) {
					LmdbOperatorFeedbackStats feedback = statistics.estimatorRuntime().feedback();
					assertNotNull(feedback);
					feedback.recordFanout(33L, LmdbLeoSurfaceStats.BoundPosition.OBJECT, 44L, 123L, 1L);
					assertTrue(feedback.evidence(LeoSurfaceKey.fanout(33L, "object", 44L)).isPresent(),
							"an independent real physical observation reached the provider");
				}
			}
			if (kind.equals("unknown-child")) {
				assertTrue(Files.isRegularFile(alternate.resolve("synopsis.leo")),
						"the independent LEO channel used the authenticated alternate");
			}
		}
	}

	private static Filter filter() {
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { ?s <urn:alternate-safety:p> ?o . FILTER(?o = 1) }", null).getTupleExpr();
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		Filter[] found = new Filter[1];
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter value) {
				if (found[0] == null) {
					found[0] = value;
				}
				super.meet(value);
			}
		});
		assertNotNull(found[0]);
		return found[0];
	}

	private static LmdbStoreConfig config() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc").setSketchEstimatorEnabled(false)
				.setBackgroundRawSamplingEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		return config;
	}
}
